// Preenche o modelo HTML com os dados do banco e prepara o arquivo para o conversor.
const d = $json.dados || {};
let html = d.template_html || '<p>Modelo de contrato não configurado.</p>';
html = html.replace(/\{\{(\w+)\}\}/g, (_, k) => (d[k] ?? '').toString());
const full = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;font-size:12pt;margin:2.5cm}h1{font-size:16pt;text-align:center}h2{font-size:13pt;margin-top:1.2em}</style></head><body>${html}</body></html>`;
return [{ json: { ...$json, html_len: full.length, nome_arquivo: `contrato-${$json.contract_id}.pdf` },
          binary: { html: await this.helpers.prepareBinaryData(Buffer.from(full, 'utf8'), 'index.html', 'text/html') } }];

// Monta a requisição multipart do GraphQL da Autentique (createDocument com upload).
// Signatário recebe pelo WhatsApp (delivery_method WHATSAPP) e por e-mail quando houver.
const src = $('Dados do contrato + token do provedor').item.json;
const signer = { name: src.cliente_nome, action: 'SIGN', delivery_method: 'DELIVERY_METHOD_WHATSAPP', phone: `+${src.wa_id}` };
if (src.cliente_email) signer.email = src.cliente_email;
const sandbox = String(src.provider_config?.sandbox ?? 'false') === 'true';
const operations = {
  query: `mutation($document: DocumentInput!, $signers: [SignerInput!]!, $file: Upload!, $sandbox: Boolean) {
    createDocument(document: $document, signers: $signers, file: $file, sandbox: $sandbox) {
      id name signatures { public_id name email action { name } link { short_link } }
    } }`,
  variables: { document: { name: `Contrato de honorários - ${src.cliente_nome}` }, signers: [signer], file: null, sandbox }
};
return [{ json: { ...src, operations: JSON.stringify(operations), map: JSON.stringify({ '0': ['variables.file'] }) }, binary: { pdf: $input.item.binary.pdf } }];

// Normaliza o evento da Autentique. Interessa: documento finalizado (todas as assinaturas feitas).
const b = $json.body || {};
const type = b.event?.type || b.type || '';
const doc = b.object || b.document || b.data || {};
const finished = /finish|complet|signed/i.test(type) || doc.signatures?.every?.(s => s.signed || s.signed_at) === true;
const pdf = doc.files?.signed || doc.files?.pades || doc.signed_file || null;
return [{ json: { type, ref: doc.id || b.document_id || null, pdf_url: pdf, finished, raw_len: JSON.stringify(b).length } }];
